clrFehlerHell = ColorValue("#FCE8E6");
clrGesperrt = ColorValue("#9AA0A6");
clrGesperrtHell = ColorValue("#EEF0F3");
stInArbeit = "InArbeit";
stAbschluss = "Abschluss";
stAbgeschlossen = "Abgeschlossen";
cfgNachholTage = Max(
    0,
