                    Notify("Bitte zuerst die vorherigen Kategorien abschließen.", NotificationType.Warning),
                // (F1) neue Fotos hochladen – nur für Punkte, die (noch) n.i.O. sind; schon hochgeladene (Url gesetzt) nicht erneut
